export function codexSandboxPolicy({home,owned,port,sentinel}) {
 assert.equal(typeof home,'string');assert.ok(Number.isSafeInteger(port)&&port>0&&port<=65535);
 for(const value of [home,owned,sentinel])assert.ok(typeof value==='string'&&path.isAbsolute(value)&&!/["\
]/.test(value));
 return `(version 1)
(allow default)
(deny network*)
(allow network-outbound (remote ip "localhost:${port}"))
(deny mach-lookup)
(deny file-read* file-write* (subpath "${home}/.codex") (subpath "${home}/.claude") (literal "${home}/.claude.json") (subpath "${home}/.agents") (subpath "${home}/.pi") (subpath "${home}/.dsh") (subpath "${home}/.config") (subpath "${home}/Library/Keychains") (subpath "/Library/Keychains") (subpath "${home}/Library/Application Support/Codex") (subpath "${home}/Library/Application Support/Claude"))
(deny file-write*)
(allow file-write* (subpath "${owned}"))
(deny file-read* file-write* (literal "${sentinel}"))
`;
}
